// Photos are generated by `npm run photos` into cropped/ (3:4 portrait) and
// puzzle/ (square, wider framing for the front-cover puzzle pieces).
const images = import.meta.glob('../assets/authors/{cropped,puzzle}/*.jpg', {
  eager: true,
  import: 'default',
})
const photosFor = (id) => ({
  photo: images[`../assets/authors/cropped/${id}.jpg`],
  puzzlePhoto: images[`../assets/authors/puzzle/${id}.jpg`],
})

/**
 * @typedef {Object} Author
 * @property {string} id
 * @property {string} firstName
 * @property {string} lastName
 * @property {string} role
 * @property {string} photo        bundled URL of the 3:4 portrait (back cover)
 * @property {string} puzzlePhoto  bundled URL of the square puzzle crop (front cover)
 * @property {string|null} takeaway  shown on the back cover; null = not written yet
 */

/**
 * Display order on both covers. On the front cover the n-th author fills the
 * n-th missing puzzle piece (see covers/puzzle/layout.js).
 * @type {Author[]}
 */
